CREATE TABLE notification_evaluation(id bigserial PRIMARY KEY,outbox_id bigint NOT NULL REFERENCES stream_outbox(id),event_id uuid NOT NULL REFERENCES financial_event(id),source_id text NOT NULL REFERENCES source_registry(id),event_type text NOT NULL,source_level text NOT NULL,qualification_rule_id text NOT NULL,qualification_rule_version text NOT NULL,qualification_evaluated_at timestamptz NOT NULL DEFAULT clock_timestamp(),qualified boolean NOT NULL,rejection_reason text,subscription_id uuid REFERENCES stream_connection(id),delivery_status text NOT NULL,evaluation_mode text NOT NULL CHECK(evaluation_mode='LIVE_RULE_AUDIT'));
CREATE INDEX notification_evaluation_page ON notification_evaluation(outbox_id DESC,id DESC);
CREATE TRIGGER notification_evaluation_immutable BEFORE UPDATE OR DELETE ON notification_evaluation FOR EACH ROW EXECUTE FUNCTION protect_raw_evidence();
CREATE TABLE notification_audit_cursor(name text PRIMARY KEY,last_outbox bigint NOT NULL);
INSERT INTO notification_audit_cursor SELECT 'LIVE_RULE_AUDIT',COALESCE(max(id),0) FROM stream_outbox;
CREATE VIEW qualification_explanation AS SELECT q.*,e.category event_type,s.level source_level,
 'OFFICIAL_ATOMIC_ALERT'::text qualification_rule_id,'资格门禁-2.0'::text qualification_rule_version,
 (q.important_alert_eligible AND l.status='APPROVED' AND l.storage_allowed AND (l.valid_until IS NULL OR l.valid_until>now()) AND EXISTS(SELECT 1 FROM notification_review nr JOIN fact_candidate f ON f.id=nr.fact_id WHERE nr.outbox_id=q.id AND nr.message_class='IMPORTANT_ALERT' AND COALESCE((SELECT decision FROM fact_review v WHERE v.fact_id=f.id ORDER BY created_at DESC,id DESC LIMIT 1),f.verification_status) IN('FIELD_MATCHED','INDEPENDENT_SUPPORTED'))) qualified,
 CASE WHEN q.notification_kind='HISTORICAL_BACKFILL' THEN '历史回填：不得作为实时重大提醒' WHEN s.level<>'L0' THEN '聚合线索：未核验且须单独订阅' WHEN l.status<>'APPROVED' OR NOT l.storage_allowed OR l.valid_until<=now() THEN '许可未确认或已失效' WHEN NOT EXISTS(SELECT 1 FROM notification_review nr WHERE nr.outbox_id=q.id AND nr.message_class='IMPORTANT_ALERT') THEN '尚无重大消息资格审核；官方消息投递另按订阅规则执行' WHEN NOT EXISTS(SELECT 1 FROM notification_review nr JOIN fact_candidate f ON f.id=nr.fact_id WHERE nr.outbox_id=q.id AND nr.message_class='IMPORTANT_ALERT' AND COALESCE((SELECT decision FROM fact_review v WHERE v.fact_id=f.id ORDER BY created_at DESC,id DESC LIMIT 1),f.verification_status) IN('FIELD_MATCHED','INDEPENDENT_SUPPORTED')) THEN '当前事实核验资格不足或已撤销' ELSE NULL END rejection_reason
 FROM notification_qualification q JOIN financial_event e ON e.id=q.event_id JOIN source_registry s ON s.id=q.source_id JOIN source_license l ON l.source_id=q.source_id;
CREATE TABLE collector_batch_commit(job_id uuid NOT NULL REFERENCES ingestion_job(id),batch_id varchar(14) NOT NULL REFERENCES gdelt_batch(batch_id),fetched integer NOT NULL,inserted integer NOT NULL,duplicates integer NOT NULL,committed_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(job_id,batch_id),CHECK(fetched=inserted+duplicates));
CREATE TRIGGER collector_commit_immutable BEFORE UPDATE OR DELETE ON collector_batch_commit FOR EACH ROW EXECUTE FUNCTION protect_raw_evidence();
CREATE VIEW collection_task_accounting AS SELECT j.id,j.source_id,j.status task_status,j.new_count declared_new,j.fetched_count declared_fetched,j.duplicate_count declared_duplicates,j.error_code,j.started_at,j.finished_at,
 COALESCE(r.saved,0) committed_raw_records,COALESCE(r.positions,0) committed_outbox_positions,
 CASE WHEN j.status='FAILED' AND COALESCE(r.saved,0)>0 THEN 'PARTIAL_COMMITTED' WHEN j.status='FAILED' THEN 'NO_RECORD_COMMIT' WHEN j.status='RUNNING' THEN 'IN_PROGRESS' ELSE 'TASK_FINISHED' END commit_state,
 CASE WHEN j.status<>'RUNNING' AND j.new_count<>COALESCE(r.saved,0) THEN 'COUNTER_MISMATCH' ELSE 'MATCHED_OR_RUNNING' END counter_state,
 COALESCE((SELECT count(*) FROM collector_batch_commit c WHERE c.job_id=j.id),0) recorded_committed_batches,
 CASE WHEN EXISTS(SELECT 1 FROM collector_batch_commit c WHERE c.job_id=j.id) THEN 'TRANSACTION_RECEIPTS' ELSE 'HISTORICAL_RAW_PROVENANCE_ONLY' END batch_count_basis
 FROM ingestion_job j LEFT JOIN LATERAL(SELECT count(DISTINCT r.id) saved,count(DISTINCT o.id) positions FROM raw_evidence r LEFT JOIN stream_outbox o ON o.evidence_id=r.id WHERE r.job_id=j.id)r ON true;
